import pandas as pd

def solve(data):
     revenue = pd.Series(data['revenue'], dtype=float)
     cost = pd.Series(data['cost'], dtype=float)
     profit = revenue - cost
     return {key: None if pd.isna(value) else float(value) for key, value in profit.items()}
